sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float amount;
uniform float invert_alpha;
uniform float red;
uniform float green;
uniform float blue;

half4 main(float2 coord) {
    half4 c = image.eval(coord);
    half a = c.a;
    half3 rgb = c.rgb;
    if (a > 0.001) {
        rgb = rgb / a;
    }
    half3 inv = 1.0 - rgb;
    half3 out_rgb = mix(rgb, inv, half(amount) * half3(red, green, blue));
    half out_a = c.a;
    if (invert_alpha == 1.0) {
        out_a = 1.0 - a;
    }
    out_rgb = out_rgb * out_a;
    return half4(out_rgb, out_a);
}
